package com.trading.historical_service.signals

/**
 * Three chronological blocks: training -> calibration -> untouched holdout.
 * Model scores on calibration are generated by an expanding-window model that
 * cannot see the calibration row's outcome. Holdout scoring freezes the model
 * after calibration, preventing later test-label leakage.
 */
object CalibratedWalkForward {
    data class Report(
        val raw: HoldoutMetrics,
        val calibrated: HoldoutMetrics,
        val calibrationSize: Int,
        val holdoutStartMs: Long
    )

    fun evaluate(
        rows: List<EvaluationExample>,
        calibrationStartMs: Long,
        holdoutStartMs: Long
    ): Report {
        require(calibrationStartMs < holdoutStartMs)
        require(rows.zipWithNext().all { (a, b) -> a.predictionTimeMs <= b.predictionTimeMs })
        require(rows.all { it.labelAvailableAtMs > it.predictionTimeMs })

        val calibrationRows = rows.filter {
            it.predictionTimeMs >= calibrationStartMs &&
                it.predictionTimeMs < holdoutStartMs &&
                it.labelAvailableAtMs <= holdoutStartMs
        }
        val holdoutRows = rows.filter { it.predictionTimeMs >= holdoutStartMs }
        require(calibrationRows.size >= ProbabilityCalibration.MIN_CALIBRATION_ROWS)
        require(holdoutRows.size >= WalkForwardMetrics.MIN_TEST_ROWS)
        val calibrationScores = calibrationRows.map { row ->
            val prior = rows.filter {
                it.predictionTimeMs < row.predictionTimeMs &&
                    it.labelAvailableAtMs <= row.predictionTimeMs &&
                    it.predictionTimeMs < calibrationStartMs
            }
            require(prior.size >= LogisticBaseline.MIN_TRAIN_ROWS) {
                "Insufficient pre-calibration training rows"
            }
            CalibrationExample(
                predictedAtMs = row.predictionTimeMs,
                labelAvailableAtMs = row.labelAvailableAtMs,
                rawProbabilityUp = LogisticBaseline.fit(prior).predict(row),
                actualUp = row.up
            )
        }
        val calibrator = ProbabilityCalibration.fit(calibrationScores, holdoutStartMs)
        val finalTrain = rows.filter {
            it.predictionTimeMs < calibrationStartMs &&
                it.labelAvailableAtMs <= calibrationStartMs
        }
        require(finalTrain.size >= LogisticBaseline.MIN_TRAIN_ROWS)
        val model = LogisticBaseline.fit(finalTrain)
        val raw = holdoutRows.map { ScoredObservation(model.predict(it), it.up) }
        val adjusted = raw.map { ScoredObservation(calibrator.transform(it.probabilityUp), it.actualUp) }
        return Report(
            raw = WalkForwardMetrics.evaluate(LogisticBaseline.VERSION, raw),
            calibrated = WalkForwardMetrics.evaluate("platt-" + LogisticBaseline.VERSION, adjusted),
            calibrationSize = calibrationScores.size,
            holdoutStartMs = holdoutStartMs
        )
    }
}
